export function getLevelDesign(levelNumber) {
  if (!Number.isInteger(levelNumber) || levelNumber < 8 || levelNumber > 40) return null;
  const design = DESIGNS[levelNumber];
  if (!design) return null;
  return {
    ...design,
    platforms: design.platforms.map(([ratio, height, width]) => ({ xRatio: ratio, height, width })),
    enemyRatios: [...design.enemies],
    coinRatios: [...design.coins],
  };
}

export const AUTHORED_LEVEL_NUMBERS = Object.freeze(Object.keys(DESIGNS).map(Number));
